/* View BEO: document preview and signing controls from frame 286:13379. */
function beoSigningDraft(){const f=$('#cx-esign-form');if(!f)return;const v=formValues('#cx-esign-form');Object.assign(state.quote,{beoMessage:v.message,reminder:v.reminder,beoDocuments:{beo:!!v.beo,contract:!!v.contract}});}
function beoPreviewDocument(tab){
 const q=state.quote,r=state.request,t=totals(q),rooms=q.rooms.filter(x=>x.qty>0),rows=quoteRows(q),roomAmount=rooms.reduce((s,x)=>s+x.qty*x.rate*nights(),0);
 const miniTable=(heads,rs)=>'<table class="beo-mini-table"><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rs.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 const signatures='<div class="beo-mini-signatures"><div><p>'+esc(q.signature?.name||'Client signature pending')+'</p><small>'+esc(name())+' · Organizer</small></div><div><p>'+esc(q.venueConfirmed?q.venueSignature?.name||'Jordan Reyes':'Venue signature pending')+'</p><small>Jordan Reyes · Events Manager</small></div></div>';
 let body=tab==='contract'?'<h3>GROUP BOOKING CONTRACT</h3><div class="beo-contract-copy">'+contractBody()+'</div>':tab==='agenda'?'<h3>EVENT AGENDA</h3>'+miniTable(['Day','Time','Session','Location'],scheduleRows()):'<h3>ROOM SETUP</h3>'+miniTable(['Room type','Qty','Rate','Total'],rooms.map(x=>[esc(x.type)+' ('+nights()+' nights)',x.qty,money(x.rate),money(x.qty*x.rate*nights())]))+'<h3>SPACE AND ADD-ONS</h3>'+miniTable(['Item','Qty','Rate','Total'],rows.slice(rooms.length).map(x=>[x[0],x[1],x[3],x[4]]))+'<div class="beo-mini-totals">'+line('Rooms',money(roomAmount))+line('Space and add-ons',money((t.beforeDiscount||t.subtotal)-roomAmount))+(t.discount?line('Discount','−'+money(t.discount)):'')+line('Taxes ('+(q.tax?'10':'0')+'%)',money(t.tax))+(t.storedValueAmount?line('Stored Value','−'+money(t.storedValueAmount)):'')+line('Total',money(t.total),'total')+'</div>';
 return '<article class="beo-design-document"><div class="beo-mini-brand"><div><b>CEDAR VALLEY</b><small>Retreat & Conference Center</small></div><div><small>'+({beo:'BANQUET EVENT ORDER',contract:'GROUP BOOKING CONTRACT',agenda:'EVENT AGENDA'})[tab]+'</small><strong>GBR-008</strong></div></div><div class="beo-mini-facts">'+[['GROUP',r.group],['ORGANIZER',name()],['DATES',dates()+' · '+nights()+' nights'],['ROOMS',requestRoomSummary(r)]].map(([k,v])=>'<div><small>'+k+'</small><p>'+esc(v)+'</p></div>').join('')+'</div>'+body+(q.beoNotes?'<div class="beo-event-notes"><h3>EVENT NOTES</h3><p>'+esc(q.beoNotes)+'</p></div>':'')+signatures+'</article>';
}
beoPreview=function(){
 const q=state.quote,tab=ops().beoTab||'beo',docs=q.beoDocuments||{beo:true,contract:true};
 const status=q.signature&&q.venueConfirmed?'Signed':q.signature?'Awaiting venue signature':q.signingSent?'Sent':'Draft';
 const signer=(who,role,email,signed)=>'<div class="beo-signer"><div><b>'+esc(who)+' · '+role+'</b><small>'+esc(email)+'</small></div><span class="beo-sign-status '+(signed?'signed':'')+'">'+(signed?'Signed':q.signingSent?'Not signed':'Not sent')+'</span></div>';
 return '<div class="admin beo-preview-page">'+sfNav()+'<header class="beo-view-header"><div><small>Group Block '+button('GBR-008','open-block','beo-record-link')+' · Documents</small><div class="beo-heading-row"><h1>Banquet Event Order</h1><span class="beo-sign-status '+(status==='Draft'?'draft':status==='Signed'?'signed':'')+'">'+status+'</span></div><p>Version 2 · Updated Sep 12, 2026 · Preview as the client will see it</p></div><div class="row">'+button('Edit BEO','cx-edit-beo')+button('Download','download-beo')+button('Send for e-signature','cx-send-sign','primary')+'</div></header><div class="beo-view-layout"><section class="beo-preview-card"><div class="document-tabs">'+[['BEO','beo'],['Contract','contract'],['Agenda','agenda']].map(([title,id])=>button(title,'cx-beo-tab-'+id,tab===id?'primary':'')).join('')+'</div><div class="beo-document-canvas">'+beoPreviewDocument(tab)+'</div></section><aside class="beo-side"><section class="beo-sign-card"><h2>E-signature</h2><form id="cx-esign-form"><div><h3>Documents to sign</h3>'+check('BEO_GBR-008.pdf','beo',docs.beo)+check('Contract_GBR-008.pdf','contract',docs.contract)+'</div><div><h3>Signers (in order)</h3>'+signer(name(),'Client',state.request.email,q.signature)+signer('Jordan Reyes','Venue','events@cedarvalley.example',q.venueConfirmed)+'</div>'+textarea('Message to the client','message',q.beoMessage??'Hi '+state.request.first+', please review the BEO and sign the contract to confirm your retreat. The deposit is paid in the next step.')+select('Reminder','reminder',q.reminder||'After 3 days if unsigned',['After 3 days if unsigned','After 7 days if unsigned','No reminder'])+'<div>'+button('Send for e-signature','cx-send-sign','primary')+'</div></form></section><section class="beo-after-card"><h2>After you send</h2><p>• '+esc(state.request.first)+' signs first with her secure link; then Jordan Reyes countersigns for the venue.</p><p>• You see who signed and when on the Contract card.</p><p>• The signed files are saved to Files automatically.</p></section></aside></div></div>';
};
const beoDesignHandle=handle;
handle=function(a,el){if(a.startsWith('cx-beo-tab-')||a==='cx-edit-beo')beoSigningDraft();if(a==='cx-send-sign'){beoSigningDraft();save();}return beoDesignHandle(a,el);};
render();
